// <auto-generated />
namespace Alpha.Results.Site.Services.Impl
{
    using Criteria;
    using DataAccesses;
    using Fanex.Data.Repository;
    using Models;

    public class AuthorizationService : IAuthorizationService
    {
        private readonly IAuthorizationDataAccess authorizationDataAccess;

        public AuthorizationService(IAuthorizationDataAccess authorizationDataAccess)
        {
            this.authorizationDataAccess = authorizationDataAccess;
        }

        public bool IsBelongingOnPage(Actor actor, int custId, int subAccountId, long transId = 0)
            => IsConsolidatedGroupBelonging(actor, custId, subAccountId, transId)
            || IsBelonging(actor, custId, subAccountId, transId);

        private bool IsConsolidatedGroupBelonging(Actor actor, int custId, int subAccountId, long transId)
        {
            ICriteria criteria = new CheckConsolidatedGroupBelongingCriteria(actor.ActorId, custId, subAccountId, transId);

            var belongingInfo = authorizationDataAccess.IsBelonging(criteria);

            return belongingInfo.RoleId > 0
                && belongingInfo.IsActive;
        }

        private bool IsBelonging(Actor actor, int custId, int subAccountId, long transId)
        {
            ICriteria criteria = new CheckBelongingCriteria(actor.ActorId, custId, subAccountId, transId);

            var belongingInfo = authorizationDataAccess.IsBelonging(criteria);

            return 0 < belongingInfo.RoleId && belongingInfo.RoleId < actor.ActorRoleId
                && belongingInfo.IsActive;
        }
    }
}